# --- native model.py ---
"""Independent beam-relay interpreter; no supplied grids or labels are embedded."""
from collections import deque

DIRS = ((-1, 0), (0, 1), (1, 0), (0, -1))
RIVALS = ('paint_all_objects', 'only_initial_hit', 'ignore_markers',
          'bbox_beams', 'highlight_largest', 'highlight_first', 'opposite_finish',
          'single_deepest', 'single_port', 'terminal_only')


def grid_check(g):
    if (type(g) is not list or not 1 <= len(g) <= 30 or type(g[0]) is not list
            or not 1 <= len(g[0]) <= 30 or any(type(row) is not list or len(row) != len(g[0])
            or any(type(v) is not int or not 0 <= v <= 9 for v in row) for row in g)):
        raise ValueError('Expected a rectangular 1..30 exact-integer grid')


def parts(g):
    grid_check(g)
    if any(v not in (1, 2, 3, 4, 8) for row in g for v in row):
        raise ValueError('Beam input palette is 1,2,3,4,8')
    h, w = len(g), len(g[0]); todo={(r,c) for r in range(h) for c in range(w) if g[r][c] in (1,3)}
    objects=[]
    while todo:
        start=min(todo); todo.remove(start); stack=[start];cells={start}
        while stack:
            r,c=stack.pop()
            for dr,dc in DIRS:
                p=(r+dr,c+dc)
                if p in todo: todo.remove(p);cells.add(p);stack.append(p)
        markers=sorted(p for p in cells if g[p[0]][p[1]]==3)
        blue=cells-set(markers)
        if not blue or not markers: raise ValueError('Each relay needs blue body and green port')
        r0,c0=min(p[0] for p in cells),min(p[1] for p in cells)
        r1,c1=max(p[0] for p in cells),max(p[1] for p in cells)
        candidates=[]
        for dr,dc in DIRS:
            boundary=all((r==r0 if dr<0 else r==r1 if dr>0 else c==c0 if dc<0 else c==c1) for r,c in markers)
            if boundary and all((r-dr,c-dc) in blue for r,c in markers):candidates.append((dr,dc))
        if len(candidates)!=1:raise ValueError('Green port must identify a unique outward normal')
        if len(markers)>1 and any(abs(a[0]-b[0])+abs(a[1]-b[1])!=1 for a,b in zip(markers,markers[1:])):
            raise ValueError('Green port must be contiguous')
        objects.append({'cells':sorted(cells),'markers':markers,'direction':candidates[0],'bbox':(r0,c0,r1,c1)})
    gun=[(r,c) for r in range(h) for c in range(w) if g[r][c]==4]
    if len(gun)!=1:raise ValueError('Exactly one yellow emitter is required')
    r,c=gun[0];dirs=[(-dr,-dc) for dr,dc in DIRS if 0<=r+dr<h and 0<=c+dc<w and g[r+dr][c+dc]==2]
    if len(dirs)!=1:raise ValueError('Emitter needs exactly one adjacent red tail direction')
    dr,dc=dirs[0]
    red={(rr,cc) for rr in range(h) for cc in range(w) if g[rr][cc]==2}
    tail=set();rr,cc=r-dr,c-dc
    while 0<=rr<h and 0<=cc<w and g[rr][cc]==2:tail.add((rr,cc));rr-=dr;cc-=dc
    if red!=tail:raise ValueError('All red cells must form the emitter tail')
    return objects,gun[0],dirs[0]


def analyze(g, *, mode='normal'):
    objects,gun,direction=parts(g);h,w=len(g),len(g[0])
    lookup={p:i for i,o in enumerate(objects) for p in o['cells']}
    out=[[2 if v in (2,4) else 8 for v in row] for row in g]
    q=deque([(gun,direction,0)]);depths={};rays=[]
    while q:
        (r,c),(dr,dc),depth=q.popleft();r+=dr;c+=dc;path=[];hit=None
        while 0<=r<h and 0<=c<w:
            path.append((r,c));out[r][c]=2
            if (r,c) in lookup:hit=lookup[(r,c)];break
            r+=dr;c+=dc
        rays.append({'cells':path,'target':hit,'parent_depth':depth})
        if hit is None or hit in depths:continue
        depths[hit]=depth+1;o=objects[hit]
        for rr,cc in o['cells']:out[rr][cc]=2
        if mode=='only_initial_hit':continue
        if mode=='ignore_markers':
            r0,c0,r1,c1=o['bbox'];origin=(r0 if dr<0 else r1 if dr>0 else r,c0 if dc<0 else c1 if dc>0 else c)
            q.append((origin,(dr,dc),depth+1));continue
        markers=o['markers'][:1] if mode=='single_port' else o['markers']
        if mode=='bbox_beams':
            r0,c0,r1,c1=o['bbox'];er,ec=o['direction']
            markers=[(r0 if er<0 else r1,cc) for cc in range(c0,c1+1)] if er else [(rr,c0 if ec<0 else c1) for rr in range(r0,r1+1)]
        q.extend((p,o['direction'],depth+1) for p in markers)
    return {'objects':objects,'depths':depths,'rays':rays,'output':out}


def solve(g, finish='trace_only', *, mode='normal'):
    if finish not in ('trace_only','highlight_deepest'):raise ValueError('Undeclared finish')
    info=analyze(g,mode=mode);out=info['output'];depths=info['depths']
    if finish=='highlight_deepest' and depths:
        deepest=max(depths.values())
        for i,d in depths.items():
            if d==deepest:
                for r,c in info['objects'][i]['cells']:out[r][c]=9
    return out


def rival(g,finish,name):
    if name not in RIVALS:raise ValueError('Unknown rival')
    if name in ('only_initial_hit','ignore_markers','bbox_beams','single_port'):return solve(g,finish,mode=name)
    if name=='opposite_finish':return solve(g,'trace_only' if finish=='highlight_deepest' else 'highlight_deepest')
    info=analyze(g);out=[row[:] for row in info['output']]
    if name=='paint_all_objects':
        for o in info['objects']:
            for r,c in o['cells']:out[r][c]=2
        if finish=='highlight_deepest' and info['depths']:
            for i,d in info['depths'].items():
                if d==max(info['depths'].values()):
                    for r,c in info['objects'][i]['cells']:out[r][c]=9
        return out
    if name=='terminal_only':
        lookup={p:i for i,o in enumerate(info['objects']) for p in o['cells']}
        for i in info['depths']:
            o=info['objects'][i];dr,dc=o['direction'];hits_object=False
            for r,c in o['markers']:
                r+=dr;c+=dc
                while 0<=r<len(g) and 0<=c<len(g[0]):
                    if (r,c) in lookup:hits_object=True;break
                    r+=dr;c+=dc
            if not hits_object:
                for r,c in o['cells']:out[r][c]=9
        return out
    # Wrong global selection is an added 9 highlight under either setting;
    # default demos refute the extra operation, alternative demos refute its key.
    if info['depths']:
        if name=='single_deepest':
            selected=min(i for i,d in info['depths'].items() if d==max(info['depths'].values()))
        else:
            selected=max(info['depths'],key=lambda i:len(info['objects'][i]['cells'])) if name=='highlight_largest' else min(info['depths'])
        for r,c in info['objects'][selected]['cells']:out[r][c]=9
    return out

# --- native sampler.py ---
"""Constructive relay networks with inert distractors, cycles, and D4 variation."""
import hashlib
import random

PATHS = (
    ((2,0),(2,1),(1,1),(1,2),(0,2)),
    ((2,1),(1,1),(1,0),(0,0),(0,1),(0,2)),
    ((2,2),(2,1),(1,1),(1,2),(0,2),(0,1),(0,0)),
    ((2,0),(2,1),(1,1),(1,0)), # closed loop
    ((2,1),(1,1),(1,2)),
    ((2,2),(1,2),(1,1),(2,1),(2,0),(1,0),(0,0)),
)


def integer(value,lo,hi,name):
    if type(value) is not int or not lo<=value<=hi:raise ValueError(f'{name} must be an integer in {lo}..{hi}')
    return value


def transform(g,index):
    integer(index,0,7,'transform')
    out=[row[:] for row in g]
    if index>=4:out=[row[::-1] for row in out]
    for _ in range(index%4):out=[list(row) for row in zip(*out[::-1])]
    return out


def fork(rng,h,w,b):
    """Wide upward port fans out into two disjoint, equally deep child relays.

    One decoy sits outside every active ray. All margins are constructive for
    24..30 canvases; the caller applies D4 only after constructing this geometry.
    """
    g=[[8]*w for _ in range(h)]
    def box(r0,c0,r1,c1,markers):
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if g[r][c]!=8:raise AssertionError('Fork objects overlap')
                g[r][c]=1
        for r,c in markers:g[r][c]=3
    left=5;right=w-6
    parent_top=h-7
    box(parent_top,3,h-4,w-4,[(parent_top,c) for c in range(left,right+b)])
    for center,c0,c1 in ((left,2,8),(right,w-9,w-3)):
        r0=rng.randint(8,9);r1=r0+rng.randint(2,3)
        box(r0,c0,r1,c1,[(r0,c) for c in range(center,center+b)])
    box(1,0,5,3,[(3,0)])
    g[h-2][w//2]=4;g[h-1][w//2]=2
    return g


def draw(seed,index,*,split='train',grid_h=None,grid_w=None,transform_id=None,path_id=None,band=None):
    integer(seed,0,2**63-1,'seed');integer(index,0,2**31-1,'sample_index')
    if split not in ('train','test','production'):raise ValueError('Unknown stream')
    rng=random.Random(int.from_bytes(hashlib.sha256(f'beam-v1:{seed}:{split}:{index}'.encode()).digest(),'big'))
    stress=split=='test' and index==3
    h=30 if stress else rng.randint(24,29)
    w=30 if stress else rng.randint(24,29)
    if grid_h is not None:h=integer(grid_h,24,30,'grid_h')
    if grid_w is not None:w=integer(grid_w,24,30,'grid_w')
    b=rng.choice((1,2)) if band is None else integer(band,1,2,'band')
    orient_rng=random.Random(f'beam-orientation-v1:{seed}:{split}:{index}')
    t=orient_rng.choice((0,2)) if split=='train' and index==0 else orient_rng.randrange(8)
    if transform_id is not None:t=integer(transform_id,0,7,'transform_id')
    # Controls describe the returned grid, not the pre-rotation workspace.
    if t%2:h,w=w,h
    cap=3 if min(h,w)==30 else 2
    ys=[cap,(cap+h-b-cap-3)//2,h-b-cap-3]
    xs=[cap,(cap+w-b-cap)//2,w-b-cap]
    # Demo 1 is a cycle (no terminal relay); demo 2 and query profile 1 teach fan-out
    # and an entire tied deepest class. Explicit path controls always win.
    scheduled = (3 if split=='train' and index==0 else
                 6 if split in ('train','test') and index==1 else rng.randrange(len(PATHS)))
    k=scheduled if path_id is None else integer(path_id,0,6,'path_id')
    if k==6:return transform(fork(rng,h,w,b),t)
    path=PATHS[k]
    g=[[8]*w for _ in range(h)]
    occupied=set()
    # Include at least one unreachable, deliberately large decoy. At stress
    # size all nine nodes occupy the full canvas rather than merely padding it.
    rest=sorted(set((r,c) for r in range(3) for c in range(3))-set(path))
    rng.shuffle(rest);decoys=rest if stress else rest[:rng.randint(1,len(rest))]
    for slot in list(path)+decoys:
        i=path.index(slot) if slot in path else None
        radius=cap if i==0 or i is None else rng.randint(1,max(1,cap-1))
        ry=radius;rx=radius
        y,x=ys[slot[0]],xs[slot[1]]
        r0,r1=y-ry,y+b+ry-1;c0,c1=x-rx,x+b+rx-1
        # Corner clipping changes occupied area without changing aligned ports.
        clipped=rng.choice((False,True))
        cells={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
               if not(clipped and r in (r0,r1) and c in (c0,c1))}
        if occupied & cells:raise AssertionError('Construction overlapped relay cells')
        occupied|=cells
        for r,c in cells:g[r][c]=1
        if i is None:dr,dc=rng.choice(((-1,0),(0,1),(1,0),(0,-1)))
        elif i+1<len(path):dr,dc=path[i+1][0]-slot[0],path[i+1][1]-slot[1]
        elif k==3:dr,dc=1,0
        elif slot[0]==0:dr,dc=-1,0
        else:dr,dc=0,1
        markers=([(r0 if dr<0 else r1,c) for c in range(x,x+b)] if dr else
                 [(r,c0 if dc<0 else c1) for r in range(y,y+b)])
        for r,c in markers:g[r][c]=3
    gun_c=xs[path[0][1]]+rng.randrange(b)
    g[h-2][gun_c]=4;g[h-1][gun_c]=2
    # The first lesson separates causal depth from terminal-only selection.
    return transform(g,t)


# Ordinary input-only registration entry point. Racket remains label authority.
GENERATOR_ID = TASK_ID = 'public_eval_5961cc34'
RULE_TASK_ID = 'ee_5961cc34'
VERSION = '1.1.0'
EXAMPLES_NEEDED = 2
SUMMARY = 'Trace red beams through blue relays using every green port; erase unreached objects.'
AXES = {
 'grid_h':{'type':'int','valid':'24..30','default':'24..29'},
 'grid_w':{'type':'int','valid':'24..30','default':'24..29'},
 'path_id':{'type':'int','valid':'0..6','default':'six routes; 6 selects fan-out'},
 'band':{'type':'int','valid':'1..2','default':'terminal/chain port width'},
 'transform_id':{'type':'int','valid':'0..7','default':'D4'}
}
INVARIANTS=['one yellow emitter with straight red tail',
            'unique outward normal per green port',
            'inactive relays erased', 'all green cells emit one ray']

def generate(seed,sample_index,*,difficulty=None,**overrides):
    if difficulty not in (None,'easy','medium','hard'):raise ValueError('Unknown difficulty')
    if set(overrides)-set(AXES):raise ValueError('Unknown controls')
    if 'path_id' not in overrides and difficulty is not None:
        overrides['path_id']={'easy':4,'medium':1,'hard':5}[difficulty]
    return draw(seed,sample_index,split='production',**overrides)

def self_check(grid,*,difficulty=None,meta=None):
    try:parts(grid)
    except (ValueError,TypeError,IndexError) as exc:return [str(exc)]
    return []
